# -*- coding: utf-8 -*-
# DEF_MVP_V1（防衛戦・部門べつ ベスト3）
#   1) サーバ側の戦闘計算のなかで、せめ／ねばり／まもり を「自分の力でわった値」として出す。
#   2) 部門が成り立つ日だけ 台帳に行を作る。ここで progress は1文字も触らない。
#   3) 児童が progress を読むときに、台帳の未適用ぶんだけを配る。
#      枠を先に予約 → 加算 → 失敗したら解放、という作法にそろえてある。
#   4) PUT /api/student/progress に _defMvpCoinsApplied の照合を足す。
#      クライアントの台帳が水増しされていてもコインは1枚も動かさない。
#   5) GET /api/defense/status に my_def_record を足す（読むだけ。書き込みはしない）。
#   6) public/defense2.js に 部門べつの ベスト3 と 自分のきろく の 見た目を足す。
# 金額も資格も サーバ側の定数だけで決める。クライアントの申告は一切つかわない。
# 表のつくりかたは ここでは流さない（migrations/0034 を D1 MCP から直接流してある）。
# アンカーが一致しなければ 何も書かずに止まる（fail-closed）。
import io
import sys

CHAIN_EXPECT = 82


def chain_count(s):
    i = s.index("app.get('/', async (c) => {")
    j = s.index("app.get('/logout'", i)
    return s[i:j].count('.replace(')


def apply_to(path, guard, steps):
    s = io.open(path, encoding='utf-8').read()
    if guard in s:
        print('すでに適用ずみ: %s' % path)
        return s, False
    for label, a, b in steps:
        n = s.count(a)
        if n != 1:
            print('NG: %s のアンカー %s が %d 件（期待 1）' % (path, label, n))
            sys.exit(1)
    for label, a, b in steps:
        s = s.replace(a, b, 1)
    return s, True


